/**
 * Motion review sheet for clinicians: every exercise (and every step of a
 * multi-step stretch) at its key frames, with the source of the hand
 * placement and a link to the reference video at that moment.
 */
import { useApp } from '../../data/store';
import { EXERCISES, KIND_LABEL, type Exercise } from '../../rehab/exercises';
import { planFor, programFor, type Plan } from '../../rehab/motion';
import { mmss, videoLink } from '../../rehab/stretches';
import { AppBar, Notice } from '../components/common';
import { HAND_COLOR } from '../rehab/face2d';
import { RehabStill, holdTime } from '../rehab/stage';

interface Key {
  label: string;
  t: number;
}

function keyTimes(ex: Exercise, plan: Plan, step: number): Key[] {
  const blocks = plan.blocks.filter((b) => b.step === step && b.rep <= 1);
  const at = (key: string, k: number) => {
    const b = blocks.find((x) => x.phase.key === key);
    return b ? b.start + b.phase.dur * k : null;
  };
  if (programFor(ex.id) || ex.kind === 'nmr' || ex.kind === 'dissociation') {
    return [
      { label: '손 대기 · 준비', t: at('prepare', 0.95) ?? 0 },
      { label: '최대 스트레칭 · 유지', t: holdTime(plan, step) },
      { label: '풀기', t: at('release', 0.5) ?? 0 },
    ];
  }
  if (ex.kind === 'massage') return [0.1, 0.45, 0.85].map((k, i) => ({ label: ['시작', '중간', '끝'][i]!, t: at('stroke', k) ?? 0 }));
  if (ex.kind === 'relax')
    return [
      { label: '들이마심', t: 3.9 },
      { label: '내쉬는 중', t: 6.5 },
      { label: '다 내쉼', t: 9.9 },
    ];
  return plan.blocks.slice(0, 4).map((b, i) => ({ label: `${i + 1}단계`, t: b.start + 1 }));
}

export function AnimReview() {
  const { profile } = useApp();
  const side = profile?.affectedSide ?? 'left';
  const view = { affectedSide: side, mirror: true, showMuscle: true, callouts: false, ghostHands: true, compact: true } as const;
  return (
    <>
      <AppBar
        title="동작 그림 검수"
        sub={`${EXERCISES.length}개 운동 · 마비 쪽 ${side === 'left' ? '왼쪽' : '오른쪽'} · 거울 보기`}
        onBack
      />
      <main class="main">
        <div class="card tight">
          <Notice>
            <span class="small">
              재활 전문가 검수용 화면입니다. 손 A(파랑, 자물쇠 = 고정)·손 B(주황, 화살표 = 미는 방향), 목표 근육(붉은 띠)이 원 동작과 같은지
              확인하세요. “격자 측정”은 참고 프레임 위에 얼굴 좌표 격자를 겹쳐 읽은 위치, “영상 판독”은 영상 프레임을 보고 옮긴 위치입니다.
            </span>
          </Notice>
        </div>
        {EXERCISES.map((ex) => {
          const plan = planFor(ex);
          const program = programFor(ex.id);
          const steps = program ? program.steps.map((s, i) => ({ i, s })) : [{ i: 0, s: null }];
          return (
            <div class="card tight">
              <div class="card-head">
                <b>{ex.title}</b>
                <span class="chip">{KIND_LABEL[ex.kind]}</span>
              </div>
              {steps.map(({ i, s }) => (
                <div class="stack">
                  {s && (
                    <div class="row between xsmall">
                      <span>
                        <b>
                          {steps.length > 1 ? `${i + 1}. ` : ''}
                          {s.title}
                        </b>{' '}
                        <span class={`chip ${s.source === 'frame-grid' ? 'accent' : ''}`}>
                          {s.source === 'frame-grid' ? '격자 측정' : '영상 판독'}
                        </span>
                      </span>
                      {s.videoAt >= 0 && (
                        <a href={videoLink(s.videoAt)} target="_blank" rel="noopener noreferrer">
                          영상 {mmss(s.videoAt)}
                        </a>
                      )}
                    </div>
                  )}
                  <div class="review-row">
                    {keyTimes(ex, plan, i).map(({ label, t }) => (
                      <figure>
                        <div class="fsr-thumb">
                          <RehabStill ex={ex} t={t} view={view} />
                        </div>
                        <figcaption class="xsmall muted">{label}</figcaption>
                      </figure>
                    ))}
                  </div>
                  {s && (
                    <>
                      <ul class="xsmall contact-list">
                        {s.contacts.map((c) => (
                          <li>
                            <i style={{ background: HAND_COLOR[c.hand] }} />손 {c.hand} {c.label}
                            {c.intraoral ? '(입안)' : ''}: {c.land} — {c.act}
                          </li>
                        ))}
                      </ul>
                      <p class="xsmall ink2">영상 해설: {s.narration}</p>
                    </>
                  )}
                </div>
              ))}
            </div>
          );
        })}
      </main>
    </>
  );
}
